"""Execute the real 'Flush user-logged metrics' block from grpo_trainer.py under a 2-proc gloo group."""

import sys
import textwrap
from collections import defaultdict

import torch
import torch.distributed as dist
from accelerate import Accelerator
from accelerate.utils import gather_object

SRC, SCENARIO = sys.argv[1], sys.argv[2]


def extract_block(path):
    lines = open(path).read().split("\n")
    start = next(i for i, l in enumerate(lines) if "Flush user-logged metrics" in l)
    end = next(i for i, l in enumerate(lines) if i > start and l.strip() == "self._pending_metrics.clear()")
    return textwrap.dedent("\n".join(lines[start : end + 1]))


class Stub:
    def __init__(self, accelerator, pending):
        self.accelerator = accelerator
        self._pending_metrics = pending
        self._metrics = {"train": defaultdict(list), "eval": defaultdict(list)}


def pending_for(scenario, rank):
    p = defaultdict(list)
    if scenario == "rank0_only":  # exactly what train.py does: log_metric guarded by rank == 0
        if rank == 0:
            p["answer_parse_rate"].append(2 / 3)
    elif scenario == "both_ranks":
        p["answer_parse_rate"].append(0.5 if rank == 0 else 0.75)
    elif scenario == "disjoint":
        if rank == 0:
            p["answer_parse_rate"].append(0.5)
        else:
            p["zz_other"].extend([1.0, 3.0])
    elif scenario == "unequal_counts":
        p["answer_parse_rate"].extend([0.25, 0.75] if rank == 0 else [1.0])
    elif scenario == "none_logged":
        pass
    else:
        raise SystemExit(f"unknown scenario {scenario}")
    return p


def main():
    acc = Accelerator()
    rank = acc.process_index
    block = extract_block(SRC)
    stub = Stub(acc, pending_for(SCENARIO, rank))
    ns = {"self": stub, "mode": "train", "device": acc.device, "gather_object": gather_object, "torch": torch}
    exec(compile(block, "<flush_block>", "exec"), ns)

    result = dict(stub._metrics["train"])
    # the block must leave no stale local keys behind (defaultdict pollution check)
    leftover = sorted(stub._pending_metrics)
    all_results = gather_object([(rank, result, leftover)])
    if rank == 0:
        values = [r for _, r, _ in all_results]
        agree = all(v == values[0] for v in values)
        print(f"scenario={SCENARIO} per_rank={all_results}", flush=True)
        print(f"scenario={SCENARIO} ranks_agree={agree} leftover_pending={leftover}", flush=True)
        print(f"scenario={SCENARIO} PASS" if agree else f"scenario={SCENARIO} FAIL", flush=True)
    dist.barrier()


if __name__ == "__main__":
    main()

